import {webkit,devices} from 'playwright';
const browser=await webkit.launch({headless:true});
const page=await browser.newPage({...devices['iPhone 13'],userAgent:devices['iPhone 13'].userAgent+' KAKAOTALK'});
page.setDefaultTimeout(18000);
const actionBodies=[];
const member=(id,name,gender,cls,role='member',year=1990)=>({id,name,gender,cls,role,year,age:String(Math.floor((2026-year)/10)*10),type:'member',state:'out',totalGames:0,joinedAt:Date.now()-60000});
const membersA=[member('mgr','배솜다리','여','C','manager',1990),...Array.from({length:17},(_,i)=>member('m'+(i+1),'회원'+(i+1),(i%2?'여':'남'),['A','B','C','D','E'][i%5],'member',1980+i))];
const membersB=[member('mgrb','배솜다리','여','C','manager',1990),member('b1','비회원1','남','B'),member('b2','비회원2','여','D')];
const state=gid=>({data:{dayKey:'2026-08-28',courtCount:4,courtNames:['1코트','2코트','3코트','4코트'],members:gid==='grp_b'?membersB:membersA,queue:[],pendingGames:[],games:[],history:[],pairCounts:{},attendancePolls:[]},user:{role:'manager',displayName:'배솜다리',memberId:gid==='grp_b'?'mgrb':'mgr',globalAdmin:false,groupId:gid,groupName:gid==='grp_b'?'B모임':'테스트모임'},group:{groupId:gid,name:gid==='grp_b'?'B모임':'테스트모임'},groups:[{groupId:'grp_a',name:'테스트모임'},{groupId:'grp_b',name:'B모임'}]});
await page.addInitScript(()=>{localStorage.setItem('kokmatch_v1_6_reset_once','done');localStorage.setItem('kokmatch_token','qa-token-a');localStorage.setItem('kokmatch_group_id','grp_a');window.__qaTouchEvents=[];document.addEventListener('touchstart',e=>window.__qaTouchEvents.push(['start',e.target?.tagName,e.target?.className,e.target?.textContent?.trim()?.slice(0,30)]),true);document.addEventListener('touchend',e=>window.__qaTouchEvents.push(['end',e.target?.tagName,e.target?.className,e.target?.textContent?.trim()?.slice(0,30)]),true)});
await page.route('**/latest-version.json*',r=>r.fulfill({status:200,contentType:'application/json',body:JSON.stringify({version:54,label:'5.4',semanticVersion:'5.4'})}));
await page.route('https://wjelumpbjklfrdjxbesj.supabase.co/functions/v1/**',async route=>{const req=route.request(),u=new URL(req.url()),path=u.pathname;let body={};try{body=req.postData()?JSON.parse(req.postData()):{}}catch{}let out={};if(path.endsWith('/kokmatch-multi-api')){const api=u.searchParams.get('api');if(api==='state')out=state(u.searchParams.get('groupId')||'grp_a');else if(api==='action'){actionBodies.push(body);out={data:state(body.groupId||'grp_a').data}}}else if(path.endsWith('/kokmatch-state-v46')){const g=u.searchParams.get('groupId')||'grp_a';out={...state(g),memberCount:state(g).data.members.length}}else if(path.endsWith('/kokmatch-auth-v38')){if(body.action==='my_memberships')out={memberships:[{groupId:'grp_a',groupName:'테스트모임',memberId:'mgr',role:'manager',roleLabel:'모임관리자'},{groupId:'grp_b',groupName:'B모임',memberId:'mgrb',role:'manager',roleLabel:'모임관리자'}]};else if(body.action==='switch_group')out={success:true,token:'qa-token-'+body.groupId,groupId:body.groupId,groupName:body.groupId==='grp_b'?'B모임':'테스트모임',memberId:body.groupId==='grp_b'?'mgrb':'mgr',role:'manager',roleLabel:'모임관리자'}}else if(path.endsWith('/kokmatch-profile-v53'))out=u.searchParams.get('full')==='1'?{image:'',fullImage:''}:{profiles:{}};else if(path.endsWith('/kokmatch-updater'))out={version:0,label:'0.0',autoUpdate:false};else out={data:state(body.groupId||'grp_a').data};await route.fulfill({status:200,contentType:'application/json',body:JSON.stringify(out)})});
const errors=[];page.on('pageerror',e=>errors.push(e.message));
async function forceNonButtonTap(buttonLocator,label){const loc=buttonLocator.first();await loc.waitFor({state:'visible'});await loc.scrollIntoViewIfNeeded();await page.waitForTimeout(220);const info=await loc.evaluate(btn=>{const card=btn.closest('#members .memberCard');return{id:card?.dataset?.memberId22||card?.dataset?.memberId46||card?.dataset?.memberId||'',text:(btn.textContent||'').trim()}});const b=await loc.boundingBox();if(!b)throw new Error('no box '+label);const x=b.x+b.width/2,y=b.y+b.height/2;const hit=await page.evaluate(({x,y})=>document.elementsFromPoint(x,y).slice(0,7).map(el=>({tag:el.tagName,cls:el.className,text:(el.textContent||'').trim().slice(0,30)})),{x,y});console.log('HIT '+label,JSON.stringify(hit));if(hit[0]?.tag==='BUTTON')throw new Error('button still top target '+label+' '+JSON.stringify(hit));await page.touchscreen.tap(x,y);await page.waitForTimeout(160);console.log('EVENTS '+label,JSON.stringify(await page.evaluate(()=>window.__qaTouchEvents.splice(0))));console.log('TRACE '+label,await page.evaluate(()=>window.__kokmatchV27Last||''));return info;}
await page.goto('http://127.0.0.1:4173/ios-diagnostic.html?qa=v271coord',{waitUntil:'domcontentloaded'});
await page.waitForFunction(()=>window.__kokmatchIOSMemberSlotFix==='27.1'&&window.__kokmatchRosterCanonical==='22.2');
await page.waitForFunction(()=>document.querySelectorAll('#members .memberCard').length===10&&document.querySelectorAll('#members .memberBtns button').length>0);
await page.addStyleTag({content:'#members .memberBtns button{pointer-events:none!important}'});
await page.evaluate(()=>{window.openEditMember=()=>{throw new Error('legacy edit must not run')};window.setOther=()=>{throw new Error('legacy setOther must not run')}});
const enter=page.locator('#members .memberBtns button').filter({hasText:'입장'}).first();const enterInfo=await forceNonButtonTap(enter,'coordinate attendance');await page.waitForTimeout(500);if(!actionBodies.some(x=>x.action==='set_member_attendance'&&x.memberId===enterInfo.id&&x.mode==='waiting'))throw new Error('coordinate attendance missing '+JSON.stringify({enterInfo,actionBodies}));console.log('PASS coordinate attendance');
const watch=page.locator('#members .memberBtns button').filter({hasText:'관람'}).first();const watchInfo=await forceNonButtonTap(watch,'coordinate spectator');await page.waitForTimeout(500);if(!actionBodies.some(x=>x.action==='set_member_attendance'&&x.memberId===watchInfo.id&&x.mode==='spectator'))throw new Error('coordinate spectator missing '+JSON.stringify({watchInfo,actionBodies}));console.log('PASS coordinate spectator');
const edit=page.locator('#members .memberBtns button').filter({hasText:'수정'}).first();const editInfo=await forceNonButtonTap(edit,'coordinate edit');await page.waitForSelector('#modal.on #fmName');const expected=membersA.find(m=>m.id===editInfo.id)?.name;if(await page.locator('#fmName').inputValue()!==expected)throw new Error('wrong coordinate edit member '+JSON.stringify({editInfo,expected,got:await page.locator('#fmName').inputValue()}));console.log('PASS coordinate edit');await page.evaluate(()=>closeModal());
await page.locator('#groupBtn').tap();await page.waitForSelector('#groupChoice26');await page.locator('#groupChoice26 button').filter({hasText:'B모임'}).tap();await page.waitForFunction(()=>window.currentGroupId==='grp_b');console.log('PASS group after coordinate fix');
if(errors.length)throw new Error('page errors '+JSON.stringify(errors));console.log('PASS V27.1 REAL-IOS NON-BUTTON TARGET ALL');await browser.close();